parameters.jsCode:
const execution = $json.execution || {};
const workflow = $json.workflow || {};
const error = execution.error || {};

const workflowId = workflow.id || 'unknown';
const workflowName = workflow.name || 'AI Lead Triage';
const executionId = execution.id || 'manual';
const nodeName = execution.lastNodeExecuted || error.node?.name || 'Unknown Node';
const errorMessage = error.message || 'Unknown error occurred';

const errorDetails = {
  stack: error.stack || null,
  name: error.name || null,
  description: error.description || null,
  timestamp: new Date().toISOString()
};

let rawPayload = null;
try {
  rawPayload = execution.data?.resultData?.runData?.[nodeName]?.[0]?.data?.main?.[0]?.[0]?.json || null;
} catch (e) {
  rawPayload = null;
}

return {
  workflow_id: workflowId,
  workflow_name: workflowName,
  execution_id: executionId,
  node_name: nodeName,
  error_message: errorMessage,
  error_details: JSON.stringify(errorDetails),
  payload: JSON.stringify(rawPayload),
  created_at: new Date().toISOString()
};

parameters.query:
INSERT INTO errors (workflow_id, workflow_name, execution_id, node_name, error_message, error_details, payload, created_at)
VALUES ($1, $2, $3, $4, $5, $6::jsonb, $7::jsonb, $8)
RETURNING id;

